tool_html='<div class="ir-tool" id="ir-tool"><div class="ir-tool-head"><span class="ir-tool-eyebrow">DNS speed check</span><button type="button" class="ir-btn-primary" id="ir-dns-run">Run DNS check</button></div><div id="ir-dns-out" aria-live="polite"><p class="ir-tool-empty">Measures how fast Cloudflare and Google public DNS answer from your browser, cached and uncached.</p></div><p class="ir-tool-note" id="ir-dns-note">This tests public resolvers from your browser. A browser cannot read which DNS server your device currently uses.</p></div>'
tool_js='''<script>(function(){var b=document.getElementById('ir-dns-run'),o=document.getElementById('ir-dns-out'),n=document.getElementById('ir-dns-note');if(!b)return;
var R=[['Cloudflare 1.1.1.1','https://cloudflare-dns.com/dns-query?type=A&name=',{accept:'application/dns-json'}],['Google 8.8.8.8','https://dns.google/resolve?type=A&name=',{}]];
function q(r,name){var s=performance.now();return fetch(r[1]+name,{headers:r[2],cache:'no-store'}).then(function(x){if(!x.ok)throw 0;return x.json()}).then(function(){return performance.now()-s})}
function med(a){a=a.slice().sort(function(x,y){return x-y});return a[Math.floor(a.length/2)]}
async function one(r){await q(r,'example.com');var c=[],u=[],i;for(i=0;i<7;i++)c.push(await q(r,'example.com'));for(i=0;i<5;i++)u.push(await q(r,'x'+Math.random().toString(36).slice(2,10)+'.example.com'));var m=Math.min.apply(null,c),k=med(u);return{name:r[0],c:m,u:k,p:Math.max(0,k-m)}}
async function run(){b.disabled=true;n.textContent='Measuring...';var res=[],i;for(i=0;i<R.length;i++){try{res.push(await one(R[i]))}catch(e){}}
if(!res.length){n.textContent='Tap to refresh.';b.disabled=false;return}
var h='<div class="ir-dns-grid">';
res.forEach(function(r){h+='<div class="ir-dns-card"><div class="ir-dns-name">'+r.name+'</div><div class="ir-dns-stats"><div><span>Round trip</span><strong>'+Math.round(r.c)+' ms</strong></div><div><span>New name</span><strong>'+Math.round(r.u)+' ms</strong></div><div><span>Penalty</span><strong>'+Math.round(r.p)+' ms</strong></div></div></div>'});
var best=res.slice().sort(function(x,y){return x.p-y.p})[0],rt=Math.min.apply(null,res.map(function(r){return r.c})),worst=Math.max.apply(null,res.map(function(r){return r.p})),t='';
t+=worst<100?'Both resolvers answer new names quickly, so if pages still feel slow the delay is more likely your connection than DNS. ':'At least one resolver adds a noticeable delay on new names. ';
if(rt>150)t+='Your round trip to public resolvers is about '+Math.round(rt)+' ms, so a public resolver may not beat your ISP\\'s nearby one. Compare with dig or Measure-Command before switching. ';
t+='Differences under about 30 ms are normal measurement noise.';
o.innerHTML=h+'</div><p class="ir-tool-note">'+t+'</p>';
n.textContent='Penalty = new-name time minus your fastest round trip. Under 100 ms is normal, 100 to 300 ms is noticeable, over 300 ms is slow (this page\\'s rule of thumb).';b.textContent='Run again';b.disabled=false}
b.addEventListener('click',run)})();</script>'''
S=dict(slug='how-to-fix-slow-dns-lookup',date='2026-10-31',date_label='31 October 2026',plan='D1',tool_html=tool_html,tool_js=tool_js,
title='How to Fix Slow DNS Lookup (Test It, Then Fix It)',headline='How to Fix Slow DNS Lookup: Measure It, Then Change the Resolver, Flush the Cache or Fix the Router',
desc='Slow DNS lookup delays every page. Measure your resolver speed live, then fix it: change DNS, flush the cache, check your router and VPN.',
kw=['how to fix slow dns lookup','slow dns lookup','dns lookup slow','how to check dns speed','change dns server','flush dns cache'],about='DNS lookup performance',section='Networking Troubleshooting',crumb='Fix Slow DNS Lookup',
h1='How to Fix <span class="ndic-highlight">Slow DNS Lookup</span>',tagline='Measure your DNS speed in your browser, then follow the fix that matches the result.',kicker='DNS &amp; Performance',cta='Test My DNS Speed',
qa_title='Fix slow DNS lookup by measuring first, then changing the resolver',
qa_body='A slow DNS lookup is a delay in turning a website name into an IP address, and it delays the whole page. Measure the lookup time first. Then switch your device or router to a faster public resolver such as 1.1.1.1, 8.8.8.8 or 9.9.9.9, flush the DNS cache, and check your VPN and router.',
og_title='How to Fix <span style="color:#38bdf8">Slow DNS Lookup</span>',og_sub='Measure it, then change the resolver or flush the cache',og_chip='DNS <span style="color:#38bdf8">42 ms</span>',
card_desc='Measure DNS lookup speed in your browser, then fix it by changing the resolver, flushing the cache and checking your router and VPN.',
panel=dict(eyebrow='Live Network panel',h3='Check the connection underneath',p='DNS is only one part of speed. The <a href="/intelligence/live-network">Live Network panel</a> shows latency, jitter and packet loss, which tell you whether the problem is DNS or the connection itself.',href='/intelligence/live-network',btn='Open Live Network'),
sections=[
('test','Test Your DNS Speed Now',''),
('what','What a DNS Lookup Is and Why It Gets Slow','<p>Every website you open has a name, and computers route by number. A DNS lookup is the step that turns the name into an <a href="/learn/what-is-an-ip-address">IP address</a>. Your device asks a resolver, usually run by your ISP or a public provider. If the resolver already knows the answer it replies at once. If it does not, it walks from the root servers to the top-level domain and then to the server that owns the name, as defined in RFC 1034 and RFC 1035.</p>'+fig(F1,'A cached answer comes straight from the resolver. A miss walks the full chain.')+'<p>Resolvers keep answers for a time set by each record, called the TTL. That is why a site you visit often loads its name quickly, and a name you have never asked for takes longer. Your browser, your operating system and often your router keep their own caches on top of that.</p><p>Lookup time matters because it comes first. Nothing else about a page can start until the name has an address, so a delay of a few hundred milliseconds is added to every new site.</p>'+fig(F5,'DNS is the first slice of a page load, so a slow lookup delays all the rest.')),
('slow','What Counts as Slow','<p>The numbers depend on where you are, because a lookup includes the trip to the resolver. That is why the tool above reports a recursion penalty: the time for a new name minus your fastest round trip to the resolver. It removes your distance from the resolver and leaves the work the resolver did.</p>'+table('Rule of thumb for the recursion penalty',['Penalty','What it usually means','Next step'],[['Under 100 ms','Normal. The resolver is doing its job','Nothing to fix here'],['100 to 300 ms','Noticeable on new sites','Try another resolver'],['Over 300 ms','Slow. Often a distant, overloaded or partly failing resolver','Change resolver, then retest']])+'<p>These ranges are this page\'s own rule of thumb, not an industry standard. If both resolvers in the tool look equally slow, the problem is more likely your connection than DNS.</p><p>Look at the round trip too. If it is already 150 ms or more, as it often is on mobile networks, distance dominates every lookup. A resolver run by your ISP can be closer and faster than a public one, so measure at the device with the commands below before and after any change.</p>'),
('causes','Common Causes of Slow Lookups','<p>Most slow lookups come from a short list of causes. A distant or overloaded resolver is the most common. A dead secondary DNS server is the classic hidden one: the device waits for the first server to time out before trying the next, so some lookups take seconds. Routers that forward DNS can add delay, VPN and security software can redirect lookups to their own servers, and a broken IPv6 path can make a device wait on an address type that never answers.</p>'+fig(F2,'Five causes behind most slow DNS lookups.')+'<p>If pages also stall after the name resolves, the cause is probably not DNS. Our guide to <a href="/learn/why-does-my-internet-speed-fluctuate">why internet speed fluctuates</a> covers congestion and Wi-Fi problems that look similar.</p>'),
('fix','Fix 1: Change the DNS Resolver','<p>Switching to a public resolver helps when your ISP\'s resolver is the slow part. It does not help if the public resolver is far from you, so test before and after. Three widely used ones are Cloudflare at 1.1.1.1 and 1.0.0.1, Google at 8.8.8.8 and 8.8.4.4, and Quad9 at 9.9.9.9. Set them on a single device, or set them on the router so every device benefits.</p>'+fig(F3,'A router-level change covers every device at once.')+table('Public resolvers compared',['Resolver','Addresses','Notes'],[['Cloudflare','1.1.1.1, 1.0.0.1','General purpose, supports DNS over HTTPS'],['Google Public DNS','8.8.8.8, 8.8.4.4','General purpose, supports DNS over HTTPS'],['Quad9','9.9.9.9','Blocks known malicious domains'],['Your ISP','Assigned automatically','Varies by provider']])+'<p>To change it on a device, open the network settings for your Wi-Fi or Ethernet connection and replace the automatic DNS servers. To change it on the router, sign in with the address from our <a href="/learn/find-router-ip-address">router IP guide</a> and look for a DNS or Internet setting.</p>'),
('flush','Fix 2: Flush the DNS Cache','<p>A cache can hold a bad or outdated answer. Flushing clears it. This is quick and safe, and your device simply asks again.</p>'+table('Flush commands',['System','Command'],[['Windows','<code class="ir-code">ipconfig /flushdns</code>'],['macOS','<code class="ir-code">sudo dscacheutil -flushcache; sudo killall -HUP mDNSResponder</code>'],['Linux (systemd-resolved)','<code class="ir-code">resolvectl flush-caches</code>']])+'<p>Browsers keep a separate cache. Restarting the browser clears it, and Chrome also has an internal DNS page for this.</p>'),
('vpn','Fix 3: Check Your VPN, Router and Security Software','<p>A VPN sends lookups to its own servers, so a slow VPN resolver means slow lookups even when your own is fast. Turn the VPN off and run the test again. The <a href="/intelligence/vpn-proxy">VPN and Proxy panel</a> shows whether your connection is routed through one. Then restart the router, since its DNS forwarder can get stuck, and check whether security or parental-control software filters DNS.</p>'),
('measure','Measure It the Manual Way','<p>You can time lookups yourself. On Windows, run <code class="ir-code">Measure-Command { Resolve-DnsName example.com }</code> in PowerShell. On Mac and Linux, run <code class="ir-code">dig example.com</code> and read the Query time line. Run it twice: the second answer is cached, and the difference shows the recursion cost.</p>'+fig(F4,'Measure first, then choose the fix that matches the result.')+'<p>For latency to a server rather than DNS, the Live Network panel reports ping and jitter. Use both numbers together before you change anything.</p>')],
logic='Explain what a lookup is, define slow in a way that removes distance, list the causes, then give fixes in order of effect and ease. Measuring comes before and after every fix so the result is verifiable.',
method='The tool sends DNS-over-HTTPS queries from your browser to Cloudflare and Google. It times one warm-up, seven repeat lookups of example.com (the fastest is your round trip) and five lookups of random new names (the median is the new-name time). It cannot see your current DNS server. The penalty ranges are a rule of thumb, and results depend on your location and connection.',
cites=[('RFC 1034: Domain Names, Concepts and Facilities','https://www.rfc-editor.org/rfc/rfc1034'),('RFC 1035: Domain Names, Implementation and Specification','https://www.rfc-editor.org/rfc/rfc1035'),('RFC 8484: DNS Queries over HTTPS (DoH)','https://www.rfc-editor.org/rfc/rfc8484'),('Cloudflare: DNS over HTTPS JSON format','https://developers.cloudflare.com/1.1.1.1/encryption/dns-over-https/make-api-requests/dns-json/'),('Google Public DNS: JSON API','https://developers.google.com/speed/public-dns/docs/doh/json'),('Microsoft Learn: Resolve-DnsName','https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname')],
faq_sub='Eleven questions on DNS lookup time, resolvers and fixes.',
faq=[('What is a DNS lookup?','It is the step that turns a website name into an IP address so your device knows where to connect.'),
('What is a good DNS lookup time?','It depends on your distance from the resolver. A cached answer is usually fast, and the difference between uncached and cached time shows the resolver\'s own work. Under about 100 ms is normal on this page\'s rule of thumb.'),
('Will changing my DNS make my internet faster?','It speeds up the lookup step, so new sites open sooner. It does not raise your download speed.'),
('My round trip is about 200 ms. Is that bad?','It is common on mobile networks and for users far from the resolver. It means distance, not DNS work, dominates. A resolver closer to you, often your ISP\'s own, may be faster, so compare at the device before switching.'),
('Which DNS server is the fastest?','It varies by location and network. Run the speed check above, then compare. Cloudflare, Google and Quad9 are common choices.'),
('Is it safe to use a public DNS resolver?','Yes for most people, but the resolver sees the names you look up, so read its privacy policy. Quad9 also blocks known malicious domains.'),
('Why is only the first visit to a site slow?','The first lookup is uncached. After that, the answer is stored for the record\'s TTL, so repeat visits are faster.'),
('Does clearing the DNS cache help?','Only if a stale or bad answer is stored. It will not fix a slow resolver, but it is quick and harmless.'),
('Can a VPN slow down DNS?','Yes. A VPN usually sends lookups to its own servers, so a slow one slows everything. Test with the VPN off.'),
('Can the browser tool see my current DNS server?','No. Browsers do not expose it, so the tool tests public resolvers instead.'),
('Should I use DNS over HTTPS?','It encrypts lookups between you and the resolver, which helps privacy on shared networks. It does not by itself make lookups faster.')])
